// 1. Get the raw text string from the previous node's output property
const inputItem = $input.item.json;
let rawText = inputItem.output || "";

// Normalize text formatting: Convert both physical and typed "\n" into uniform processing points
rawText = rawText.replace(/\\n/g, '\n').replace(/\\r/g, '\r');

// 2. CHAT ROUTER GUARDRAIL: Verify if the text contains structural keys or JSON characters
const lowerRawText = rawText.toLowerCase();
const hasIntentKey = lowerRawText.includes("intent:");
const hasBookingKey = lowerRawText.includes("booking:");
const hasJsonKey = lowerRawText.includes("{") && lowerRawText.includes("}");

// If no structured fields are present, bypass extraction and output as a normal chat
if (!hasIntentKey && !hasBookingKey && !hasJsonKey) {
    return {
        json: {
            route: "chat",
            intent: "normal chat",
            chatResponse: rawText.trim()
        }
    };
}

// 3. PRODUCTION MATRIX ENGINE: Parse key-value properties from structured text
const parsedData = {};
const lines = rawText.split(/[\n\r]+/);

for (let line of lines) {
    const colonIndex = line.indexOf(':');
    if (colonIndex !== -1) {
        let key = line.substring(0, colonIndex)
            .replace(/\\/g, '')  
            .replace(/"/g, '')   
            .replace(/\*/g, '')  
            .trim()
            .toLowerCase();

        let value = line.substring(colonIndex + 1).trim();

        // Clean up formatting artifacts from the value side
        if (value.endsWith(',')) {
            value = value.slice(0, -1).trim(); 
        }
        value = value.replace(/^\\"/, '').replace(/\\"$/, ''); 
        value = value.replace(/^"/, '').replace(/"$/, '');     

        // Safety Guardrail: Strip unfulfilled placeholder bracket strings from the AI
        if (value.startsWith('[') && value.endsWith(']')) {
            value = "";
        }

        if (key && value !== "") {
            parsedData[key] = value;
        }
    }
}

// 4. SAFE EXTRACTOR MAP: Bind keys by matching dynamic spelling variations
const intent = parsedData["intent"] || "booking confirmed";
const patientName = parsedData["patientname"] || parsedData["patient name"] || "";
const department = parsedData["department"] || "";
const doctorName = parsedData["doctorname"] || parsedData["doctor name"] || "";
const issue = parsedData["issue"] || "";
const gender = parsedData["gender"] || "";
const fee = parsedData["fee"] || "";
const calendarId = parsedData["calendarid"] || parsedData["calendar id"] || parsedData["calenader id"] || "";
const eventId = parsedData["eventid"] || parsedData["event id"] || "";
const selectedDay = parsedData["selected day"] || parsedData["selectedday"] || "";
const routingDestination = parsedData["routing destination"] || parsedData["routingdestination"] || "";

// SANITIZATION LAYER: Format Mobile Number to strictly start with 92 and remove leading 0
let rawMobile = parsedData["mobile"] || parsedData["mobile number"] || "";
let mobileNumber = "";
if (rawMobile) {
    let cleanMobile = rawMobile.replace(/[^\d]/g, '');
    if (cleanMobile.startsWith('0')) {
        cleanMobile = '92' + cleanMobile.substring(1);
    } else if (!cleanMobile.startsWith('92') && cleanMobile.length > 0) {
        cleanMobile = '92' + cleanMobile;
    }
    mobileNumber = cleanMobile;
}

// Sanitize the Age field to prevent string bleeding from inline syntax
let rawAge = parsedData["age"] || "";
if (rawAge.includes(',')) {
    rawAge = rawAge.split(',')[0];
}
const age = rawAge.replace(/[^\d]/g, '').trim(); 

// 5. DYNAMIC DATE & TIME PROCESSING FOR GOOGLE CALENDAR
let rawStartTime = parsedData["starttime"] || parsedData["start time"] || "";
let rawEndTime = parsedData["endtime"] || parsedData["end time"] || "";

let startTimeDisplay = "";
let endTimeDisplay = "";
let googleStartDate = "";
let googleEndDate = "";
let appointmentDate = parsedData["date"] || "";

// Helper function to format ISO time (14:00:00) into human readable AM/PM format
function formatToAMPM(isoTimeStr) {
    if (!isoTimeStr) return "";
    const timeRaw = isoTimeStr.substring(0, 5); 
    let hours = parseInt(timeRaw.split(':')[0], 10);
    const minutes = timeRaw.split(':')[1];
    const ampm = hours >= 12 ? 'PM' : 'AM';
    hours = hours % 12;
    hours = hours ? hours : 12; 
    return `${hours}:${minutes} ${ampm}`;
}

// Parse ISO timestamps if present
if (rawStartTime.includes('T')) {
    googleStartDate = rawStartTime; 
    const startParts = rawStartTime.split('T');
    appointmentDate = startParts[0]; 
    startTimeDisplay = formatToAMPM(startParts[1]);

    if (rawEndTime.includes('T')) {
        googleEndDate = rawEndTime; 
        const endParts = rawEndTime.split('T');
        endTimeDisplay = formatToAMPM(endParts[1]);
    }
} else {
    // Process standard non-ISO custom inputs smoothly
    startTimeDisplay = rawStartTime || parsedData["time"] || "";
    endTimeDisplay = rawEndTime || "";

    // Check if time contains a range like "10:15 AM to 10:30 AM" passed in a single string
    if (startTimeDisplay.toLowerCase().includes(' to ')) {
        const timeParts = startTimeDisplay.split(/\s+to\s+/i);
        startTimeDisplay = timeParts[0].trim();
        endTimeDisplay = timeParts[1].trim();
    }
}

// 6. Assemble structured automation object payload
const outputData = {
    route: "automation",
    intent: intent,
    patientName: patientName,
    mobileNumber: mobileNumber,
    department: department,
    doctorName: doctorName,
    issue: issue,
    age: age,
    gender: gender,
    selectedDay: selectedDay,
    date: appointmentDate,
    startTime: startTimeDisplay,
    endTime: endTimeDisplay,
    googleStartDate: googleStartDate,
    googleEndDate: googleEndDate,
    fee: fee,
    calendarId: calendarId,
    eventId: eventId,
    routingDestination: routingDestination
};

// 7. DYNAMIC SUMMARY GENERATION: Contains Patient Name & Issue strictly
if (outputData.patientName && outputData.issue) {
    outputData.summary = `${outputData.patientName} - ${outputData.issue}`;
} else if (outputData.patientName) {
    outputData.summary = `Consultation - ${outputData.patientName}`;
} else {
    outputData.summary = "Appointment Updates";
}

// 8. OVERRIDE DESCRIPTION BLOCK: Clean multi-line corporate formatting layout
outputData.description = `Patient: ${outputData.patientName}
Age: ${outputData.age}
Gender: ${outputData.gender}
Mobile: ${outputData.mobileNumber}
Dept: ${outputData.department}
Doctor: ${outputData.doctorName}
Issue: ${outputData.issue}
Date: ${outputData.date}
Start Time: ${outputData.startTime}
End Time: ${outputData.endTime}
Fee: ${outputData.fee}`;

return { json: outputData };

// 1. Get Base64 from Gemini
const base64Data = $json.candidates[0].content.parts[0].inlineData.data;
const pcmBuffer = Buffer.from(base64Data, 'base64');

// 2. Create WAV Header (44 bytes) so Cloudinary recognizes it
const wavHeader = Buffer.alloc(44);
wavHeader.write('RIFF', 0);
wavHeader.writeUInt32LE(36 + pcmBuffer.length, 4);
wavHeader.write('WAVE', 8);
wavHeader.write('fmt ', 12);
wavHeader.writeUInt32LE(16, 16);
wavHeader.writeUInt16LE(1, 20); // PCM format
wavHeader.writeUInt16LE(1, 22); // Mono
wavHeader.writeUInt32LE(24000, 24); // Sample Rate (Gemini is 24kHz)
wavHeader.writeUInt32LE(24000 * 2, 28); // Byte Rate
wavHeader.writeUInt16LE(2, 32); // Block Align
wavHeader.writeUInt16LE(16, 34); // Bits per sample
wavHeader.write('data', 36);
wavHeader.writeUInt32LE(pcmBuffer.length, 40);

// 3. Combine Header + Raw Data
const finalBuffer = Buffer.concat([wavHeader, pcmBuffer]);

// 4. Register as a file for Cloudinary
const binaryData = await this.helpers.prepareBinaryData(
    finalBuffer, 
    'appointment_voice.mp3', 
    'audio/mpeg'
);

return [
  {
    json: { resource_type: "video" },
    binary: { data: binaryData }
  }
];
